CREATE TABLE attempts(id INTEGER PRIMARY KEY,student INTEGER,lesson INTEGER,answer TEXT,correct INTEGER,created INTEGER, review_status TEXT NOT NULL DEFAULT 'auto', score REAL, max_score REAL NOT NULL DEFAULT 1, comment TEXT NOT NULL DEFAULT '', reviewed_at INTEGER, variant INTEGER NOT NULL DEFAULT -1);
CREATE TABLE cohort_members(cohort INTEGER,student INTEGER,PRIMARY KEY(cohort,student));
CREATE TABLE cohorts(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,UNIQUE(name,kind));
CREATE TABLE lessons(student INTEGER,lesson INTEGER,PRIMARY KEY(student,lesson));
CREATE TABLE materials(lesson INTEGER PRIMARY KEY,text TEXT NOT NULL,updated INTEGER);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,student INTEGER,lesson INTEGER,attempt INTEGER,message TEXT,created INTEGER,seen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE students(id INTEGER PRIMARY KEY,name TEXT NOT NULL,token TEXT UNIQUE NOT NULL,variant INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1, link_token TEXT, display_name TEXT NOT NULL DEFAULT '', about TEXT NOT NULL DEFAULT '', learning_goal TEXT NOT NULL DEFAULT '', class_group TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT 'basic', note TEXT NOT NULL DEFAULT '');
CREATE TABLE theory(student INTEGER,topic INTEGER,text TEXT,PRIMARY KEY(student,topic));
CREATE TABLE sessions(token TEXT PRIMARY KEY,role TEXT NOT NULL,student INTEGER,student_token TEXT,expires INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE INDEX attempts_student_lesson ON attempts(student,lesson,id);
CREATE INDEX attempts_review_time ON attempts(reviewed_at,id);
CREATE INDEX attempts_student_review_time ON attempts(student,reviewed_at,id);
CREATE INDEX attempts_pending ON attempts(review_status,id);
CREATE INDEX notifications_student_seen ON notifications(student,seen,id);
CREATE INDEX cohort_members_student ON cohort_members(student,cohort);
CREATE TABLE app_meta(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 0,teacher_hash TEXT);
INSERT INTO app_meta(id,revision) VALUES(1,0);
CREATE TRIGGER rev_students_insert AFTER INSERT ON students BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_students_update AFTER UPDATE ON students BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_students_delete AFTER DELETE ON students BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_lessons_insert AFTER INSERT ON lessons BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_lessons_update AFTER UPDATE ON lessons BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_lessons_delete AFTER DELETE ON lessons BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_theory_insert AFTER INSERT ON theory BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_theory_update AFTER UPDATE ON theory BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_theory_delete AFTER DELETE ON theory BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_materials_insert AFTER INSERT ON materials BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_materials_update AFTER UPDATE ON materials BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_materials_delete AFTER DELETE ON materials BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_cohorts_insert AFTER INSERT ON cohorts BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_cohorts_update AFTER UPDATE ON cohorts BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_cohorts_delete AFTER DELETE ON cohorts BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_cohort_members_insert AFTER INSERT ON cohort_members BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_cohort_members_update AFTER UPDATE ON cohort_members BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_cohort_members_delete AFTER DELETE ON cohort_members BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_attempts_insert AFTER INSERT ON attempts BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_attempts_update AFTER UPDATE ON attempts BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_attempts_delete AFTER DELETE ON attempts BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_notifications_insert AFTER INSERT ON notifications BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_notifications_update AFTER UPDATE ON notifications BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER rev_notifications_delete AFTER DELETE ON notifications BEGIN UPDATE app_meta SET revision=revision+1 WHERE id=1; END;
